import { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Progress } from "@/components/ui/progress";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
// Enhanced chart imports
import ChartContainer from "@/components/dashboard/chart-container";
import ChartInsights from "@/components/dashboard/chart-insights";
// Keep chart components for any remaining static charts
import {
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend
} from "recharts";
import {
  Plus,
  Share,
  Download,
  RefreshCw,
  ChevronDown,
  FileText,
  Mail,
  MessageSquare,
  Link2,
  Trophy,
  TrendingUp,
  GitCommit,
  Code,
  Users,
  BarChart3,
  Calendar
} from "lucide-react";
import { cn } from "@/lib/utils";
import { mockReports } from "@/lib/mock-data";
import ReportGenerationWizard from "@/components/shared/report-generation-wizard";
import WelcomeMessage from "@/components/shared/welcome-message";

export default function Reports() {
  const [selectedReport, setSelectedReport] = useState(mockReports[0]);
  const [showWizard, setShowWizard] = useState(false);
