                >
                  <Card className="bg-card/50 backdrop-blur-sm border-border/50 relative overflow-hidden group">
                    {/* Quote decoration */}
                    <motion.div
                      className="absolute top-4 right-4 text-6xl text-primary/10 leading-none"
                      animate={shouldReduceMotion ? {} : { rotate: [0, 5, 0] }}
